using System.Reflection;
using System.Text.Encodings.Web;

internal static class OperationsPage
{
    internal static string Render(string configurationUrl, string diagnosticsUrl, string site, string environment)
    {
        string version = typeof(OperationsPage).Assembly.GetName().Version?.ToString() ?? "unknown";
        return Template.Value
            .Replace("__GLOSSY__", GlossyCss.Value, StringComparison.Ordinal)
            .Replace("__SITE__", Encode(site), StringComparison.Ordinal)
            .Replace("__ENVIRONMENT__", Encode(environment), StringComparison.Ordinal)
            .Replace("__VERSION__", Encode(version), StringComparison.Ordinal)
            .Replace("__CONFIGURATION_URL__", "/handoff/configuration", StringComparison.Ordinal)
            .Replace("__DIAGNOSTICS_URL__", "/handoff/diagnostics", StringComparison.Ordinal);
    }

    private static string Encode(string value) => HtmlEncoder.Default.Encode(value);

    private static class Template
    {
        internal const string Value = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>System Operations</title><style>
:root{--bg:#00101d;--panel:#001827;--line:#15547b;--text:#eef6ff;--muted:#aac2d7;--blue:#087fff;--orange:#ffad31;--purple:#8e61ff;--green:#20d789;--red:#ff6b6b}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#00101d;color:var(--text);font:14px/1.35 'Segoe UI',Arial,sans-serif}body{padding:0 5px}a{color:inherit;text-decoration:none}.topbar{height:84px;display:grid;grid-template-columns:70px minmax(360px,1fr) 110px 220px;align-items:center;border-bottom:2px solid #4180aa}.cornerbars{height:100%;display:flex;gap:7px;padding-top:18px}.cornerbars i:first-child{width:31px;height:54px;background:var(--orange);border-radius:26px 0 0}.cornerbars i:last-child{width:25px;height:54px;background:var(--purple)}.brand{display:flex;align-items:center;gap:14px}.gear{font-size:50px;color:#2ba9ff}.brand strong{font-size:34px;display:block}.brand em{font-style:normal;color:var(--orange)}.brand small{color:#42bdff;font-weight:800}.site{background:#2727a6;border-left:18px solid var(--orange);border-radius:18px;padding:13px 18px;font-weight:800}.clock{border:1px solid #154c70;padding:14px}.frame{min-height:calc(100vh - 132px);border:1px solid #4c84a7;border-radius:25px;box-shadow:inset 0 0 24px #4db9ff44;display:grid;grid-template-columns:160px 1fr;overflow:hidden;margin-top:7px}.sidebar{background:#001b2e;border-right:1px solid #174f73;display:flex;flex-direction:column}.sidebar:before{content:'';height:63px}.sidebar a{display:flex;align-items:center;gap:17px;padding:16px;font-weight:700;font-size:16px}.sidebar a span{color:#36b9ff;font-size:25px}.sidebar a.active{background:var(--orange);color:#06111b;border-radius:0 9px 9px 0}.sidefoot{margin-top:auto;padding:25px;color:#59c0ff}.sidefoot small{display:block}main{padding:20px 10px;min-width:0}.page-head{padding:4px 12px 14px 40px;border-left:13px solid var(--purple);border-radius:18px}.page-head h1{font-size:31px;margin:0}.page-head p{margin:2px 0;color:#c1d4e4}.toolbar{float:right}.toolbar button{background:#00182