;color:#55bfff;font-size:12px}footer b{color:white}.footright{margin-left:auto}@media(max-width:900px){.workspace{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}
__GLOSSY__
</style></head><body><header class="topbar"><div class="cornerbars"><i></i><i></i></div><div class="brand"><span class="gear">✹</span><div><strong>System <em>Operations</em></strong><small>SEE THE STATE. KNOW WHERE TO ACT.</small></div></div><div class="site">__SITE__</div><div class="clock" id="clock"></div></header><div class="frame"><aside class="sidebar"><nav><a class="active" href="/"><span>▦</span>Overview</a><a href="__CONFIGURATION_URL__"><span>⚙</span>Configuration</a><a href="__DIAGNOSTICS_URL__"><span>⌁</span>Diagnostics</a><a href="/registration-lifecycle"><span>🔑</span>Registration</a></nav><div class="sidefoot"><b>System<br>Operations</b><small>v__VERSION__</small></div></aside><main><section class="page-head"><div class="toolbar"><button onclick="load()">↻ Refresh Status</button></div><h1>Operations Overview</h1><p>Integrated operational status across the Aegis management plane</p></section><section class="metrics"><div class="metric"><span>◇</span><b id="managedCount">—</b><small>Control Plane Services</small></div><div class="metric"><span>▣</span><b id="registeredCount">—</b><small>Registered Applications</small></div><div class="metric"><span>✓</span><b id="availableCount">—</b><small>Available</small></div><div class="metric"><span>▲</span><b id="attentionCount">—</b><small>Needs Attention</small></div><div class="metric"><span>⌁</span><b>__ENVIRONMENT__</b><small>Environment</small></div></section><section class="workspace"><article class="panel"><div class="panelhead"><span class="heroicon">⚙</span><div><h2>System Configuration</h2><p>Requirements · commissioning · runbooks</p></div><span id="cfgStatus" class="pill">SCANNING</span></div><div class="facts"><div><small>Service</small><b>Aegis.Configuration</b></div><div><small>Role</small><b>Configuration Authority</b></div><div><small>Site</small><b>__SITE__</b></div><div><small>Environment</small><b>__ENVIRONMENT__</b></div></div><a class="action" href="__CONFIGURATION_URL__">Open System Configuration →</a></article><article class="panel"><div class="panelhead"><span class="heroicon">⌁</span><div><h2>System Diagnostics</h2><p>Health · incidents · engineering levels</p></div><span id="diagStatus" class="pill">SCANNING</span></div><div class="facts"><div><small>Service</small><b>Aegis.Diagnostics</b></div><div><small>Role</small><b>Health Authority</b></div><div><small>Site</small><b>__SITE__</b></div><div><small>Environment</small><b>__ENVIRONMENT__</b></div></div><a class="action" href="__DIAGNOSTICS_URL__">Open System Diagnostics →</a></article></section><section class="activity"><header>◴ Operational Activity</header><div class="activityrow"><i class="dot"></i><span id="checked">SCANNING</span><b>Management-plane status refresh</b></div></section></main></div><footer><b>System Operations</b><span>│</span><span>Integrated Operations</span><div class="footright"><i class="dot"></i> Management Plane │ v__VERSION__</div></footer><script>const tick=()=>document.getElementById('clock').textContent=new Date().toLocaleString();tick();setInterval(tick,30000);async function load(){try{const r=await fetch('/api/summary',{cache:'no-store'}),d=await r.json();const systems=[d.configuration,d.diagnostics].filter(Boolean);managedCount.textContent=systems.length;registeredCount.textContent=d.registeredApplications??0;setStatus('cfgStatus',d.configuration);setStatus('diagStatus',d.diagnostics);const n=systems.filter(x=>x.available).length;availableCount.textContent=n;attentionCount.textContent=(systems.length-n)+(d.registration?.attention??0);checked.textContent='LAST SCAN '+new Date(d.checkedAt).toLocaleString().toUpperCase()}catch{managedCount.textContent='—';registeredCount.textContent='—';availableCount.textContent='—';attentionCount.textContent='—';checked.textContent='STATUS TELEMETRY UNAVAILABLE'}}function setStatus(id,x){const e=document.getElementById(id);e.textContent=x?.available?String(x.status).toUpperCase():'UNAVAILABLE';e.className='pill '+(x?.available?'available':'unavailable')}load();setInterval(load,30000)</script></body></html>
""";
    }
